begin;
select set_config('request.jwt.claim.sub',(select user_id::text from public.memberships where organization_id='0e398095-cc22-421b-ae34-7bf0df8ad7b2' and active and role='admin' limit 1),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('request.jwt.claim.sub'),'role','authenticated')::text,true);
set local role authenticated;
do $test$
declare org uuid:='0e398095-cc22-421b-ae34-7bf0df8ad7b2';o public.orders;b public.budgets;pre public.budgets;e public.calendar_events;v public.calendar_events;id1 uuid:=gen_random_uuid();id2 uuid:=gen_random_uuid();id3 uuid:=gen_random_uuid();p jsonb;original_status text;original_total numeric;original_actor text:=auth.uid()::text;
begin
 select * into o from public.orders where organization_id=org and status<>'cancelled' limit 1;
 select * into b from public.budgets where organization_id=org and document_type='budget' and status<>'cancelled' limit 1;
 select * into pre from public.budgets where organization_id=org and document_type='pre_budget' and status='draft' and client_id is not null limit 1;
 if o.id is null or b.id is null or pre.id is null then raise exception 'Fixtures indisponíveis';end if;
 original_status:=o.status::text;original_total:=o.total;
 p:=jsonb_build_object('title','TESTE TEMPORÁRIO agendamento','starts_at',now()+interval '1 day','ends_at',now()+interval '1 day 1 hour','link_kind','order','link_id',o.id,'address','Rua Teste','notes','Teste com rollback');
 e:=public.manage_calendar_appointment(org,id1,'create',p);
 e:=public.manage_calendar_appointment(org,id1,'create',p);
 if (select count(*) from public.calendar_events where id=id1)<>1 or e.order_id<>o.id or e.client_id is distinct from o.client_id or e.budget_id is not null then raise exception 'Vínculo/idempotência pedido';end if;
 e:=public.manage_calendar_appointment(org,id2,'create',p||jsonb_build_object('link_kind','budget','link_id',b.id));
 if e.budget_id<>b.id or e.order_id is not null or e.client_id is distinct from b.client_id then raise exception 'Vínculo orçamento';end if;
 e:=public.manage_calendar_appointment(org,id3,'create',p||jsonb_build_object('link_kind','pre_budget','link_id',pre.id));
 if e.budget_id<>pre.id or e.order_id is not null then raise exception 'Vínculo pré';end if;
 perform public.mark_calendar_event_sync(org,id1,'test_google_appointment','synced');
 e:=public.manage_calendar_appointment(org,id1,'update',p||jsonb_build_object('title','TESTE TEMPORÁRIO remarcado','link_kind','pre_budget','link_id',pre.id));
 if e.order_id is not null or e.budget_id<>pre.id or e.sync_status<>'pending' or e.google_event_id<>'test_google_appointment' then raise exception 'Edição/sincronização';end if;
 e:=public.manage_calendar_appointment(org,id1,'cancel','{}');e:=public.manage_calendar_appointment(org,id1,'cancel','{}');
 if e.cancelled_at is null or e.google_event_id<>'test_google_appointment' or e.sync_status<>'pending' then raise exception 'Cancelamento seguro';end if;
 begin perform public.manage_calendar_appointment(org,id1,'update',p);raise exception 'Cancelado editável';exception when check_violation then null;end;
 v:=public.schedule_pre_budget_visit(org,pre.id,now()+interval '2 days',now()+interval '2 days 1 hour','Rua Teste',null);
 begin perform public.manage_calendar_appointment(org,v.id,'update',p);raise exception 'Evento automático editável';exception when check_violation then null;end;
 begin perform public.manage_calendar_appointment(org,gen_random_uuid(),'create',p||jsonb_build_object('ends_at',now()));raise exception 'Horário inválido aceito';exception when check_violation then null;end;
 begin perform public.manage_calendar_appointment(org,gen_random_uuid(),'create',p||jsonb_build_object('link_id',gen_random_uuid()));raise exception 'Documento inexistente aceito';exception when foreign_key_violation then null;end;
 begin perform public.manage_calendar_appointment(org,gen_random_uuid(),'create',p||jsonb_build_object('link_kind','pre_budget','link_id',b.id));raise exception 'Tipo errado aceito';exception when foreign_key_violation then null;end;
 begin perform public.manage_calendar_appointment(gen_random_uuid(),gen_random_uuid(),'create',p);raise exception 'Outra organização aceita';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.manage_calendar_appointment(org,id2,'cancel','{}');raise exception 'Usuário sem acesso aceito';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',original_actor,true);
 if (select status::text from public.orders where id=o.id)<>original_status or (select total from public.orders where id=o.id)<>original_total then raise exception 'Pedido alterado pelo agendamento';end if;
 if exists(select 1 from public.payables where description like 'TESTE TEMPORÁRIO agendamento%') then raise exception 'Financeiro alterado';end if;
end $test$;
set constraints all immediate;
rollback;
